import { FC, HTMLAttributes } from 'react';

import { Card, Flex, theme, Typography } from 'antd';

import { PLATFORM_TYPES } from 'shared/consts';
import { useCommonSlice, useMedia } from 'shared/hooks';

interface IBloggerUrlProps extends HTMLAttributes<HTMLDivElement> {
	type: string;
	urls: string[];
}

export const BloggerUrl: FC<IBloggerUrlProps> = ({ type, urls, ...props }) => {
	const {
		token: { colorBgLayout },
	} = theme.useToken();
	const isMd = useMedia();
	const { bloggerSourceTypeOptions } = useCommonSlice();

	return (
		<Card style={{ backgroundColor: colorBgLayout }} {...props}>
			<Flex gap={8} vertical={isMd} align="start">
				<Flex gap={4} align="center" style={{ width: 130 }}>
					{type && PLATFORM_TYPES?.[type as keyof typeof PLATFORM_TYPES]?.icon}
					<Typography.Text>
						{bloggerSourceTypeOptions.find(({ value }) => value === type)?.label || type}
					</Typography.Text>
				</Flex>

				<Flex vertical align="start" gap={8} style={{ flexGrow: 1 }}>
					{urls.map((url) => {
						return (
							<Typography.Link key={url} href={url} target="_blank">
								{url}
							</Typography.Link>
						);
					})}
				</Flex>
			</Flex>
		</Card>
	);
};
