import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import {
	ArbitrationImageUpload,
	BloggerUrl,
	ESourceTypes,
	getNamesList,
	prepareBloggerUrls,
	SourceDetailItem,
	useGetSourceQuery,
} from 'entities/Source';
import { useCommonSlice, useNotFoundError, useTrans } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, OverlayLoader, Page, PageTitle } from 'shared/ui';

import styles from './SourceDetail.module.scss';

interface ISourceDetailProps extends HTMLAttributes<HTMLDivElement> {}

export const SourceDetail: FC<ISourceDetailProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const params = useParams<{ id: string }>();
	const { data, isFetching, error } = useGetSourceQuery(params?.id || '', { skip: !params?.id });
	const { sourceTypes, purchaseTypes } = useTrans();
	const { websiteSourceTypeOptions, bloggerSourceTypeOptions, countryOptions, contentThemesOptions } = useCommonSlice();
	const bloggerUrls = data?.type === ESourceTypes.BLOGGER ? prepareBloggerUrls(data.influencer_data.urls) : {};

	useNotFoundError(error);

	return (
		<Page {...props} className={cn(className, styles.sourceDetail)}>
			<PageTitle>{t('Детали площадки')}</PageTitle>

			{isFetching && <OverlayLoader />}

			<Flex vertical align="start" gap={24} className={styles.form}>
				<SourceDetailItem label={t('ID площадки')}>
					<Typography.Text copyable>{data?.uuid}</Typography.Text>
				</SourceDetailItem>

				{data?.type && <SourceDetailItem label={t('Тип площадки')}>{sourceTypes[data.type]}</SourceDetailItem>}

				{data?.type === ESourceTypes.WEBSITE && (
					<>
						<SourceDetailItem label={t('Название площадки')}>{data?.name}</SourceDetailItem>

						<SourceDetailItem label={t('URL площадки')}>
							<Typography.Link href={data.website_data.url} target="_blank">
								{data.website_data.url}
							</Typography.Link>
						</SourceDetailItem>

						<SourceDetailItem label={t('Тип платформы')}>
							{websiteSourceTypeOptions.find(({ value }) => value === data.website_data.platform_type)?.label ||
								data.website_data.platform_type}
						</SourceDetailItem>

						<SourceDetailItem label={t('Страна аудитории')} additionalLabel={`${t('Макс.')} 5`}>
							{getNamesList(data.website_data.countries, countryOptions)}
						</SourceDetailItem>

						<SourceDetailItem label={t('Тематика контента')} additionalLabel={`${t('Макс.')} 3`}>
							{getNamesList(data.website_data.content_themes, contentThemesOptions)}
						</SourceDetailItem>

						<SourceDetailItem label={t('У вас есть расширение?')}>
							{data.website_data.extension_exists ? t('Да') : t('Нет')}
						</SourceDetailItem>

						{data.website_data.extension_exists && (
							<SourceDetailItem label={t('Пожалуйста, укажите ссылки и укажите ОСНОВНУЮ функциональность расширения.')}>
								{data.website_data.extension_description}
							</SourceDetailItem>
						)}
					</>
				)}

				{data?.type === ESourceTypes.BLOGGER && (
					<>
						<SourceDetailItem label={t('Название площадки')}>{data?.name}</SourceDetailItem>

						<SourceDetailItem label={t('Тип платформы')} additionalLabel={`${t('Макс.')} 5`}>
							{getNamesList(data.influencer_data.platform_types, bloggerSourceTypeOptions)}
						</SourceDetailItem>

						<SourceDetailItem label={t('URL платформы ')} additionalLabel={`${t('Макс. 3 ссылки на платформу')}`}>
							{Object.keys(bloggerUrls).map((key) => (
								<BloggerUrl key={key} type={key} urls={bloggerUrls[key]} />
							))}
						</SourceDetailItem>

						<SourceDetailItem label={t('Страна аудитории')} additionalLabel={`${t('Макс.')} 5`}>
							{getNamesList(data.influencer_data.countries, countryOptions)}
						</SourceDetailItem>

						<SourceDetailItem label={t('Тематика контента')} additionalLabel={`${t('Макс.')} 3`}>
							{getNamesList(data.influencer_data.content_themes, contentThemesOptions)}
						</SourceDetailItem>
					</>
				)}

				{data?.type === ESourceTypes.ARBITRATION && (
					<>
						<SourceDetailItem
							label={t('Имя арбитражной команды')}
							info={t('Будет использовано в качестве названия площадки')}>
							{data?.name}
						</SourceDetailItem>

						{data.arbitrage_data.purchase_type && (
							<SourceDetailItem label={t('Что вы покупаете?')}>
								{purchaseTypes[data.arbitrage_data.purchase_type]}
							</SourceDetailItem>
						)}

						<SourceDetailItem label={t('URL Рекламной сети')} additionalLabel={`${t('Макс.')} 5`}>
							<Flex vertical gap={8}>
								{data.arbitrage_data.urls.map(({ url }) => (
									<Typography.Link href={url} target="_blank">
										{url}
									</Typography.Link>
								))}
							</Flex>
						</SourceDetailItem>

						<SourceDetailItem label={t('Страна аудитории')} additionalLabel={`${t('Макс.')} 5`}>
							{getNamesList(data.arbitrage_data.countries, countryOptions)}
						</SourceDetailItem>

						{data.arbitrage_data.description && (
							<SourceDetailItem label={t('Описание')}>{data.arbitrage_data.description}</SourceDetailItem>
						)}

						<ArbitrationImageUpload screenshots={data.arbitrage_data.screenshots} disabled />
					</>
				)}

				<ButtonStyleLink to={`/${EMainRoutes.SOURCES}`}>{t('Назад')}</ButtonStyleLink>
			</Flex>
		</Page>
	);
};

export default SourceDetail;
