import { FC, ReactNode } from 'react';

import { Flex, Typography } from 'antd';
import { FlexProps } from 'antd/lib';

import { InfoTooltip } from 'shared/ui';

interface ISourceDetailItemProps extends FlexProps {
	label: ReactNode;
	tooltip?: ReactNode;
	additionalLabel?: ReactNode;
	info?: ReactNode;
}

export const SourceDetailItem: FC<ISourceDetailItemProps> = ({
	label,
	tooltip,
	additionalLabel,
	children,
	info,
	...props
}) => {
	return (
		<Flex {...props} vertical gap={8}>
			<Flex gap={4} align="center">
				<Typography.Text strong>{label}</Typography.Text>
				{tooltip && <InfoTooltip text={tooltip} />}
				{additionalLabel && <Typography.Text type="secondary">({additionalLabel})</Typography.Text>}
			</Flex>
			<Flex vertical gap={2}>
				{children}
				{info && (
					<Typography.Text type="secondary" style={{ fontSize: 12 }}>
						{info}
					</Typography.Text>
				)}
			</Flex>
		</Flex>
	);
};
